def parse_duration(s: str) -> int:
    if not s:
        raise ValueError(f"Invalid duration: {s!r}")

    total_seconds = 0
    pattern = r'(\d+)([hms])'
    import re

    matches = re.findall(pattern, s)
    if not matches or sum(len(m) for m in matches) * 2 != len(s.replace('', '')):
        # More robust validation: reconstruct and compare
        restored = ''.join(f'{num}{unit}' for num, unit in matches)
        if restored != s:
            raise ValueError(f"Invalid duration: {s!r}")

    for num_str, unit in matches:
        num = int(num_str)
        if unit == 'h':
            total_seconds += num * 3600
        elif unit == 'm':
            total_seconds += num * 60
        elif unit == 's':
            total_seconds += num

    return total_seconds
```

