import os
import re
from pathlib import Path

def task_func(dir_path: str, predicates: list) -> dict:
    """
    Evaluates each item (files and directories) in a given directory against specified conditions.

    Parameters:
        dir_path (str): Path to the directory to evaluate.
        predicates (list): List of condition predicates. Each predicate can be:
            - A string interpreted as a regex pattern (matches item name).
            - A callable taking an item name and returning bool.

    Returns:
        dict: A dictionary with directory items as keys and the results of condition checks as values.

    Raises:
        ValueError: If no valid predicates are provided.
        FileNotFoundError: If the specified directory does not exist or is not a directory.
    """
    path = Path(dir_path)

    if not path.exists() or not path.is_dir():
        raise FileNotFoundError(f"Directory not found or is not a directory: {dir_path}")

    # Normalize and deduplicate predicates while validating them
    valid_predicates = []
    seen = set()

    for pred in predicates:
        if pred is None:
            continue

        if isinstance(pred, str):
            try:
                regex = re.compile(pred)
                effective = ("regex", pred)
            except re.error:
                raise ValueError(f"Invalid regex predicate: {pred}")
        elif callable(pred):
            effective = pred
        else:
            raise ValueError(f"Invalid predicate type: {type(pred)}")

        if effective not in seen:
            seen.add(effective)
            valid_predicates.append(effective)

    if not valid_predicates:
        raise ValueError("No valid predicates are provided.")

    results = {}

    for item in os.listdir(dir_path):
        item_path = path / item

        if not item_path.exists():
            continue

        # Evaluate against all predicates; result is True only if all match
        check_result = True
        for pred in valid_predicates:
            if isinstance(pred, tuple):
                pattern = pred[1]
                if not re.match(pattern, item):
                    check_result = False
                    break
            else:
                if not pred(item):
                    check_result = False
                    break

        results[item] = check_result

    return results
